INSERT INTO knowra_community.tbl_comm VALUES (1,'dev-life','개발자 라이프','개발자들의 일상, 커리어, 사이드프로젝트 이야기. 코딩 말고 삶도 나눠요.',1,'public',NULL,NULL,6,'Y','Y',2,'2026-04-01 17:22:12',NULL,NULL),(2,'ai-lab','AI 연구소','ChatGPT·LLM·이미지 AI 최신 트렌드를 가장 빠르게 공유하는 곳.',1,'public',NULL,NULL,5,'Y','Y',4,'2026-04-01 17:22:12',NULL,NULL),(3,'crypto-talk','코인토크','비트코인·이더리움·알트코인 분석과 실전 투자 경험 공유.',2,'public',NULL,NULL,5,'Y','Y',5,'2026-04-01 17:22:12',NULL,NULL),(4,'startup-hub','스타트업 허브','아이디어 검증부터 투자 유치까지. 창업가들의 생생한 경험담.',3,'public',NULL,NULL,5,'Y','Y',3,'2026-04-01 17:22:12',NULL,NULL),(5,'healthy-life','헬시라이프','운동·식단·수면. 몸과 마음을 챙기는 커뮤니티.',4,'public',NULL,NULL,5,'Y','Y',8,'2026-04-01 17:22:12',NULL,NULL),(6,'realty-talk','부동산 이야기','갭투자·전세·청약·재개발. 내 집 마련 실전 정보 공유.',2,'public',NULL,NULL,5,'Y','Y',20,'2026-04-01 17:22:12',NULL,NULL),(7,'gamers-gg','게이머스 GG','게임 공략, 티어, 신작 리뷰. 유일하게 랭크 올라가는 커뮤니티.',5,'public',NULL,NULL,5,'Y','Y',19,'2026-04-01 17:22:12',NULL,NULL),(8,'book-club','독서 클럽','한 달에 책 한 권. 함께 읽고 삶이 달라진 사람들의 이야기.',5,'public',NULL,NULL,4,'Y','Y',18,'2026-04-01 17:22:12',NULL,NULL),(9,'travel-log','트래블 로그','배낭여행·호캉스·항공권 꿀팁. 가본 사람만 아는 여행 정보.',5,'public',NULL,NULL,5,'Y','Y',7,'2026-04-01 17:22:12',NULL,NULL),(10,'music-band','뮤직 & 밴드','악기, 작곡, 공연 후기. 음악 하는 사람들의 아지트.',5,'public',NULL,NULL,4,'Y','Y',11,'2026-04-01 17:22:12',NULL,NULL),(11,'photo-lens','포토 렌즈','카메라·구도·보정. 일상을 작품으로 만드는 사진가들의 모임.',5,'public',NULL,NULL,4,'Y','Y',6,'2026-04-01 17:22:12',NULL,NULL),(12,'cookers','쿡방 클럽','오늘 뭐 먹지? 레시피·맛집·요리 팁 다 여기 있어요.',5,'public',NULL,NULL,4,'Y','Y',10,'2026-04-01 17:22:12',NULL,NULL),(13,'career-up','커리어 업','이직·면접·연봉협상·퇴사 고민. 직장인이라면 한 번쯤 겪는 모든 것.',1,'public',NULL,NULL,6,'Y','Y',12,'2026-04-01 17:22:12',NULL,NULL),(14,'rich-road','부자 되는 길','주식·ETF·배당·절세. 월급쟁이 재테크 실전 전략.',2,'public',NULL,NULL,5,'Y','Y',21,'2026-04-01 17:22:12',NULL,NULL),(15,'growth-lab','그로스 랩','독서·명상·습관·루틴. 어제보다 1% 나아지고 싶은 사람들.',5,'public',NULL,NULL,4,'Y','Y',1,'2026-04-01 17:22:12',NULL,NULL),(16,'2222','1122','222',7,'private',1,2,0,'