INSERT INTO knowra_community.tbl_comm_post VALUES (1,1,'NOTICE',2,'[공지] 커뮤니티 이용 규칙','비방·욕설·광고 금지. 즐거운 개발 이야기 나눠요!',310,4,2,'ACTIVE','Y',2,'2026-04-01 17:22:12',NULL,NULL),(2,1,'NORMAL',2,'연봉 1억 개발자, 진짜 가능한 이야기인가요?','주변에 신입 2년 만에 연봉 1억 찍었다는 사람 나왔습니다. 스톡옵션 포함이긴 한데... 5년차인 저는 아직 멀었거든요 ㅠ',1840,127,34,'ACTIVE','Y',2,'2026-04-01 17:22:12',NULL,NULL),(3,1,'NORMAL',3,'사이드 프로젝트로 월 300 버는 중인데 회사 때려칠까요?','퇴근 후 틈틈이 만든 크롬 익스텐션이 갑자기 ProductHunt 1위 먹었어요. 지금 월 300만원 정도 들어오는데 나와도 될까요?',3210,256,89,'ACTIVE','Y',3,'2026-04-01 17:22:12',NULL,NULL),(4,1,'NORMAL',4,'ChatGPT로 코드 짜면 실력이 늘까요 줄까요?','요즘 ChatGPT 없으면 코딩 못 하겠다는 분들 많은데, 저는 오히려 문제 해결 능력이 줄어드는 느낌이에요.',2560,198,67,'ACTIVE','Y',4,'2026-04-01 17:22:12',NULL,NULL),(5,1,'NORMAL',12,'비전공 6개월 독학으로 네카라쿠배 합격 후기','문과 출신 29살에 무작정 개발 공부 시작해서 6개월 만에 카카오 합격했습니다. 커리큘럼 다 공유할게요.',5670,489,124,'ACTIVE','Y',12,'2026-04-01 17:22:12',NULL,NULL),(6,1,'NORMAL',2,'스타트업 vs 대기업, 5년 다 다녀본 솔직 비교','스타트업 3년, 대기업 2년. 연봉·성장·워라밸·안정성 모두 다른 두 세계. 솔직하게 공유합니다.',2890,211,78,'ACTIVE','Y',2,'2026-04-01 17:22:12',NULL,NULL),(7,2,'NOTICE',4,'[공지] AI 연구소 운영 방침','출처 없는 허위 정보는 삭제됩니다. 논문·실험 결과·프롬프트 팁 모두 환영.',280,9,2,'ACTIVE','Y',4,'2026-04-01 17:22:12',NULL,'2026-04-04 01:59:02'),(8,2,'NORMAL',4,'GPT-5 나오면 개발자 직업 진짜 없어질까? 현직자 시각','GPT-4o 나왔을 때도 같은 말 나왔는데 설계·아키텍처 결정은 여전히 사람이 해요. 근데 GPT-5 스펙 보면... 솔직히 무서운 부분도 있습니다.',4120,312,98,'ACTIVE','Y',4,'2026-04-01 17:22:12',NULL,NULL),(9,2,'NORMAL',16,'Sora 영상 생성 AI 직접 써봤는데 충격 받은 이유','유튜브 썸네일, 광고 영상, 쇼츠 콘텐츠를 텍스트 몇 줄로 만들었어요. 크리에이터들한테 미칠 영향이 상상 이상입니다.',3780,287,76,'ACTIVE','Y',16,'2026-04-01 17:22:12',NULL,NULL),(10,2,'NORMAL',2,'프롬프트 엔지니어링 6개월 독학 핵심 정리 (무료 공유)','Chain of thought·Few-shot·RAG까지 실무에서 바로 쓸 수 있게 정리했어요. 노션 링크 공유합니다.',6230,521,143,'ACTIVE','Y',2,'2026-04-01 17:22:12',NULL,NULL),(11,2,'NORMAL',4,'AI가 내 일자리 빼앗기 전에 내가 AI를 활용하는 법','같은 직군에서도 AI 잘 쓰는 사람이 못 쓰는 사람 몫까지 가져가는 게 현실이에요.',5110,398,117,'ACTIVE','Y',4,'2026-04-01 17:22:12',NULL,NULL),(12,2,'NORMAL',23,'Claude vs ChatGPT vs Gemini 실무 사용 1년 비교','코딩·글쓰기·분석·창작 분야별로 어떤 AI가 진짜 잘하는지 솔