INSERT INTO knowra_post.tbl_post VALUES (1,'NOTICE',1,'[공지] Knowra 일반 게시판 이용 안내','광고·비방·무분별한 홍보는 삭제됩니다. 지식과 경험을 자유롭게 나눠요.',900,12,3,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(2,'NORMAL',1,'개발자로 살면서 가장 잘한 결정 3가지','커리어·학습·워라밸. 10년 차 개발자로서 돌아보면 이 세 가지 결정이 가장 큰 차이를 만들었습니다.',4259,312,47,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(3,'NORMAL',1,'매일 30분 글쓰기가 개발자 커리어에 미친 영향','TIL 블로그를 1년간 운영하면서 면접에서 받은 혜택, 채용 담당자한테 연락 온 횟수, 실제 이직 성공까지 공유합니다.',5686,446,89,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,'2026-04-09 17:30:12'),(4,'NORMAL',1,'오픈소스 기여 처음 시작하는 방법 (완전 초보 가이드)','Good First Issue 찾는 법, PR 올리는 절차, 리뷰 받는 요령. 첫 머지까지 걸린 시간과 배운 점 공유합니다.',3452,267,54,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(5,'NORMAL',1,'기술 면접 200번 보고 나서 느낀 것들','합격·불합격 다 경험한 기술 면접 200번. 어떤 회사가 좋은 면접을 하는지, 어떤 준비가 실제로 통했는지 솔직하게.',6804,535,112,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,'2026-04-09 16:35:00'),(6,'NORMAL',1,'내가 쓰는 개발 도구 스택 2026 버전','IDE·터미널·노트·브라우저·AI 보조 도구까지. 매년 바뀌는 스택 중 진짜 생산성에 도움된 것들만 골랐습니다.',2906,198,38,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(7,'NORMAL',31,'풀스택 혼자 개발해서 월 200 버는 방법','Next.js + Spring Boot + AWS. 사이드프로젝트 3개 운영하면서 쌓은 아키텍처 결정들을 공유합니다.',3129,243,56,'ACTIVE','Y',31,'2026-04-01 17:31:51',NULL,NULL),(8,'NORMAL',32,'ChatGPT API로 나만의 AI 도구 만드는 법 (비용 월 3천원)','OpenAI API 호출 최적화, 프롬프트 캐싱, 스트리밍 응답. 토큰 절약하면서 쓸만한 AI 앱 만드는 법.',4564,367,78,'ACTIVE','Y',32,'2026-04-01 17:31:51',NULL,NULL),(9,'NORMAL',34,'그로스 해킹으로 앱 MAU 0→10만 만든 방법','SEO·바이럴 루프·리텐션 개선. 광고비 0원으로 10만 MAU까지 간 실제 전략을 공개합니다.',5340,423,94,'ACTIVE','Y',34,'2026-04-01 17:31:51',NULL,NULL),(10,'NORMAL',35,'프리랜서 5년차가 말하는 장단점 총정리','수입·자유·외로움·세금·건강보험. 회사 다니다 프리랜서 된 사람이 경험한 현실을 솔직하게.',4121,334,72,'ACTIVE','Y',35,'2026-04-01 17:31:51',NULL,NULL),(11,'NORMAL',36,'이더리움 스마트 컨트랙트 개발 입문 가이드','Solidity 기초부터 Hardhat 테스트까지. 백엔드 개발자가 Web3 입문하면서 헤맸던 것들 정리.',2780,189,43,'ACTIVE','Y',36,'2026-04-01 17:31:51',NULL,NULL),(12,'NORMAL',37,'영어 공부 3년, 말하기 두렵지 않게 된 방법','문법보다 입 훈련이 먼저였어요. 매일 15분 쉐도잉으로 어떻게 달라졌는지 데이터와 함께 공유합니다.',3890,312,67,'ACTIVE','Y',37,'2026-04-01 17:31:51',NULL,NULL),(13,'NORMAL',39,'의료 AI가 실제 병원에서 사용되는 방법','영상 판독·처방 보조·환자 분류. 현직 의료 AI 연구자가 말하는 현실과 한계.',5120,421,94,'ACTIVE','Y',39,'2026-04-01 17:31:51',NULL,NULL),(14,'NORMAL',40,'유튜브 구독자 10만 가기까지 실제로 한 것들','콘텐츠 기획·썸네일·알고리즘·협업. 2년간 올린 영상 300개에서 배운 것들을 압축합니다.',4892,389,83,'ACTIVE','Y',40,'2026-04-01 17:31:51',NULL,NULL),(15,'NORMAL',42,'스타트업 CFO가 말하는 런웨이 관리 실전','캐시플로우 예측, 번 레이트 관리, 투자 라운드 타이밍. 실제 숫자로 보는 스타트업 재무 생존법.',3560,278,61,'ACTIVE','Y',42,'2026-04-01 17:31:51',NULL,NULL),(16,'NORMAL',43,'홈서버 구축으로 월 클라우드 비용 10만원 절약한 방법','Proxmox + Docker + Nginx. 중고 미니PC 하나로 NAS·CI/CD·개인 서비스 돌리는 셋업 공유.',4120,334,72,'ACTIVE','Y',43,'2026-04-01 17:31:51',NULL,NULL),(17,'NORMAL',44,'집에서 식당 수준의 파스타 만드는 3가지 비밀','면수·버터 마운팅·치즈의 비율. 레스토랑 셰프한테 직접 배운 것들을 가정 주방에 맞게 정리했습니다.',5670,456,98,'ACTIVE','Y',44,'2026-04-01 17:31:51',NULL,NULL),(18,'NORMAL',45,'비건 도시락 7일 챌린지 실제 비용과 포만감 후기','고기 없이 하루 세 끼. 영양소 충족·맛·비용 모두 잡은 일주일 메뉴 전체 공개합니다.',2560,178,38,'ACTIVE','Y',45,'2026-04-01 17:31:51',NULL,NULL),(19,'NORMAL',41,'컴공 학부생이 인턴 합격하기까지 한 것들','코딩 테스트·포트폴리오·자소서. 대기업 인턴 붙기 전에 실패한 것들도 솔직하게 씁니다.',3450,267,55,'ACTIVE','Y',41,'2026-04-01 17:31:51',NULL,NULL),(20,'NORMAL',38,'반려동물과 함께하는 국내 여행지 TOP 10','펫 동반 가능한 숙소·카페·트레킹 코스. 직접 다 가봤어요. 강아지와 2년간 여행한 기록 공유합니다.',3120,245,52,'ACTIVE','Y',38,'2026-04-01 17:31:51',NULL,NULL),(21,'NORMAL',1,'test','<img src=\"http://127.0.0.1:8080/upload/editor/2026/04/03/20260403012808468_0.png\"><p></p>',6,1,0,'ACTIVE','Y',1,'2026-04-03 13:28:17',NULL,'2026-04-19 05:55:17');
INSERT INTO knowra_post.tbl_post_cmt VALUES (1,2,31,NULL,'워라밸 고르는 결정이 생산성에도 결국 플러스더라고요. 야근 많은 팀은 번아웃 이탈률이 높아요.',34,'ACTIVE','Y',31,'2026-04-01 17:31:51',NULL,NULL),(2,2,32,1,'맞아요. 번아웃 후 회복 시간까지 합치면 장기적으로 무조건 손해예요.',21,'ACTIVE','Y',32,'2026-04-01 17:31:51',NULL,NULL),(3,2,41,NULL,'10년차 관점에서 학습 방식에 대해 더 자세히 알 수 있을까요? 어떻게 공부하셨는지 궁금합니다.',28,'ACTIVE','Y',41,'2026-04-01 17:31:51',NULL,NULL),(4,2,1,3,'책보다는 실제 코드 읽기, 공식 문서 우선, 그리고 작은 것이라도 직접 만들기를 반복했어요.',45,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(5,3,31,NULL,'저도 TIL 블로그 6개월째 하는데 링크드인 채용 DM이 실제로 늘었어요. 효과 확실합니다.',45,'ACTIVE','Y',31,'2026-04-01 17:31:51',NULL,NULL),(6,3,37,5,'어떤 주제 위주로 쓰세요? 기술인지 커리어인지 둘 다인지 궁금해요.',22,'ACTIVE','Y',37,'2026-04-01 17:31:51',NULL,NULL),(7,3,1,6,'주로 그날 배운 기술 TIL이랑 월간 회고 글이요. 꾸준함이 제일 중요한 것 같아요.',18,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(8,3,34,NULL,'블로그 플랫폼은 어디 쓰세요? 벨로그 vs 티스토리 고민 중입니다.',31,'ACTIVE','Y',34,'2026-04-01 17:31:51',NULL,NULL),(9,3,1,8,'벨로그 추천해요. 개발자 커뮤니티 있어서 초기 유입이 훨씬 잘 돼요.',27,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(10,4,41,NULL,'Good First Issue 이 키워드 처음 알았어요. 어떻게 찾으면 되나요?',38,'ACTIVE','Y',41,'2026-04-01 17:31:51',NULL,NULL),(11,4,1,10,'github.com 에서 label:good-first-issue 검색하거나 goodfirstissue.dev 쓰면 돼요.',45,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(12,4,31,NULL,'PR 올리고 리뷰 받는 경험이 실제 협업 문화 적응에 정말 도움됐어요.',29,'ACTIVE','Y',31,'2026-04-01 17:31:51',NULL,NULL),(13,4,32,NULL,'어떤 프로젝트부터 시작하면 좋을까요? 규모 작은 게 첫 머지 받기 쉽나요?',23,'ACTIVE','Y',32,'2026-04-01 17:31:51',NULL,NULL),(14,5,35,NULL,'어떤 회사 면접 문화가 제일 인상 깊었나요?',67,'ACTIVE','Y',35,'2026-04-01 17:31:51',NULL,NULL),(15,5,1,14,'당락 여부와 관계없이 상세한 피드백을 주는 회사들이요. 문화도 좋더라고요.',52,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(16,5,42,NULL,'200번 중 합격률이 어느 정도인지 궁금해요.',34,'ACTIVE','Y',42,'2026-04-01 17:31:51',NULL,NULL),(17,5,1,16,'약 30% 정도였어요. 준비 덜 된 상태에서 지원한 게 많아서요.',28,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(18,5,41,NULL,'코딩 테스트랑 시스템 설계 중 어떤 게 더 준비하기 어려웠나요?',41,'ACTIVE','Y',41,'2026-04-01 17:31:51',NULL,NULL),(19,7,1,NULL,'Next.js + Spring 조합이 사이드프로젝트에 딱이더라고요. AWS 비용 어떻게 관리하시나요?',56,'ACTIVE','Y',1,'2026-04-01 17:31:51',NULL,NULL),(20,7,31,19,'초반엔 EC2 프리 티어, 트래픽 붙으면 Lambda + CloudFront로 바꿨어요. 고정비 거의 없어요.',34,'ACTIVE','Y',31,'2026-04-01 17:31:51',NULL,NULL),(21,7,35,NULL,'사이드프로젝트 3개를 혼자 운영하면 유지보수가 벅차지 않나요?',28,'ACTIVE','Y',35,'2026-04-01 17:31:51',NULL,NULL),(22,7,31,21,'자동화를 많이 해뒀어요. 모니터링·배포·정기 작업 전부 자동화하니까 주 2~3시간으로 돌아가요.',23,'ACTIVE','Y',31,'2026-04-01 17:31:51',NULL,NULL),(23,8,1,NULL,'프롬프트 캐싱 쓰면 비용이 실제로 얼마나 줄어요? 비율이 궁금합니다.',45,'ACTIVE','Y',1,'2026-04-01 17:31:52',NULL,NULL),(24,8,32,23,'동일 프롬프트 재사용 기준으로 최대 90% 가까이 줄더라고요. 캐시 히트율이 핵심이에요.',38,'ACTIVE','Y',32,'2026-04-01 17:31:52',NULL,NULL),(25,8,39,NULL,'의료 쪽에서 GPT API 쓸 때 개인정보 이슈는 어떻게 처리하셨나요?',31,'ACTIVE','Y',39,'2026-04-01 17:31:52',NULL,NULL),(26,8,32,25,'온프레미스 LLM 쓰거나 Azure OpenAI 계약하면 데이터 격리 보장돼요.',27,'ACTIVE','Y',32,'2026-04-01 17:31:52',NULL,NULL),(27,12,1,NULL,'영상 판독 AI의 실제 정확도가 의사 수준에 도달했나요? 오진율이 궁금합니다.',52,'ACTIVE','Y',1,'2026-04-01 17:31:52',NULL,NULL),(28,12,39,27,'특정 질환(폐암 CT 등)에서는 이미 전문의 수준이에요. 단, 일반화는 아직 갈 길이 멀어요.',45,'ACTIVE','Y',39,'2026-04-01 17:31:52',NULL,NULL),(29,12,32,NULL,'의료 AI 데이터셋 구하는 게 제일 어렵다고 들었는데, 실제로 어떤가요?',38,'ACTIVE','Y',32,'2026-04-01 17:31:52',NULL,NULL),(30,12,39,29,'맞아요. 라벨링 된 의료 데이터가 절대적으로 부족해요. 병원 협력이 없으면 거의 불가능합니다.',34,'ACTIVE','Y',39,'2026-04-01 17:31:52',NULL,NULL),(31,12,44,NULL,'비의료인 입장에서 AI 진단 보조가 실제로 도움이 될 것 같아서 기대가 커요.',22,'ACTIVE','Y',44,'2026-04-01 17:31:52',NULL,NULL),(32,13,1,NULL,'썸네일 A/B 테스트는 어떻게 하셨나요? 유튜브 스튜디오에서 가능한가요?',48,'ACTIVE','Y',1,'2026-04-01 17:31:52',NULL,NULL),(33,13,40,32,'유튜브 스튜디오 실험 기능 쓰거나, 커뮤니티 탭 투표로 먼저 반응 봤어요.',36,'ACTIVE','Y',40,'2026-04-01 17:31:52',NULL,NULL),(34,13,34,NULL,'알고리즘보다 리텐션이 결국 핵심이라는 걸 어느 순간 깨달았어요. 비슷한 경험이에요.',41,'ACTIVE','Y',34,'2026-04-01 17:31:52',NULL,NULL),(35,13,41,NULL,'크리에이터 수익 구조가 어떻게 되는지 궁금해요. 유튜브 광고만으로는 힘들다고 하던데.',29,'ACTIVE','Y',41,'2026-04-01 17:31:52',NULL,NULL);
