-- Knowra 초기 데이터 — 운영 MariaDB 덤프에서 변환 (로컬/이관용, Flyway 마이그레이션 아님).
-- MySQL 문자열 이스케이프(\')를 그대로 해석하도록 세션 설정을 켠 뒤 넣는다.
SET standard_conforming_strings = off;


-- IDENTITY 컬럼에 값을 직접 넣었으므로 시퀀스를 최대값 뒤로 옮긴다. 안 하면 다음 INSERT 가 PK 충돌한다.
DO $$
DECLARE r RECORD; mx BIGINT;
BEGIN
  FOR r IN
    SELECT c.table_schema, c.table_name, c.column_name
    FROM information_schema.columns c
    WHERE c.is_identity = 'YES'
      AND c.table_schema NOT IN ('pg_catalog','information_schema')
  LOOP
    EXECUTE format('SELECT COALESCE(MAX(%I),0) FROM %I.%I', r.column_name, r.table_schema, r.table_name) INTO mx;
    EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN %I RESTART WITH %s',
                   r.table_schema, r.table_name, r.column_name, mx + 1);
  END LOOP;
END $$;